func withHeadlessStoreHint(err error) error {
	if !errors.Is(err, auth.ErrCredentialStoreWrite) || os.Getenv(tokenstore.BackendEnvVar) == "file" {
		return err
	}
	return fmt.Errorf("%w\n\nIf this machine has no usable OS keyring (headless server, container, CI), store tokens in a file instead:\n\n  %s=file entire login\n\nTokens are then written with 0600 permissions to tokens.json in your Entire config directory (override the location with %s).",
		err, tokenstore.BackendEnvVar, tokenstore.PathEnvVar)
}

